// Moons example: binary classification on the make_moons dataset
// (the dataset used by Lab-08 of the PyTorch reference repo
//  https://github.com/IinjyI/Hands-On-Neural-Networks).
//
// make_moons(n_samples=2000, noise=0.2, random_state=42), regenerated by
// data/make_moons.py. This demonstrates that the network learns a
// non-linear decision boundary on a larger, noisy 2D dataset.

#include "moons_data.h"
#include "nm_api.h"
#include <log.h>
#include <stdio.h>
#include <stdlib.h>

static NmTensor tensor_view(const FloatMatrix *matrix) {
  return nm_tensor_2d(matrix->values, matrix->rows, matrix->cols);
}

// Normalize features to [0, 1] range (min-max per feature)
static void normalize_features(FloatMatrix *X) {
  for (size_t j = 0; j < X->cols; j++) {
    float min_val = sm_get(X, 0, j);
    float max_val = sm_get(X, 0, j);
    for (size_t i = 1; i < X->rows; i++) {
      float val = sm_get(X, i, j);
      if (val < min_val)
        min_val = val;
      if (val > max_val)
        max_val = val;
    }
    float range = max_val - min_val;
    if (range > 1e-6f) {
      for (size_t i = 0; i < X->rows; i++)
        sm_set(X, i, j, (sm_get(X, i, j) - min_val) / range);
    }
  }
}

// The CSV is already shuffled (as make_moons does), so the last 20%
// serve as a held-out test set.
static void split_dataset(const FloatMatrix *X, const FloatMatrix *Y,
                          FloatMatrix **X_train, FloatMatrix **Y_train,
                          FloatMatrix **X_test, FloatMatrix **Y_test) {
  size_t total = X->rows;
  size_t test_size = total / 5;
  size_t train_size = total - test_size;

  *X_train = sm_create(train_size, X->cols);
  *Y_train = sm_create(train_size, Y->cols);
  *X_test = sm_create(test_size, X->cols);
  *Y_test = sm_create(test_size, Y->cols);

  for (size_t i = 0; i < train_size; i++) {
    for (size_t j = 0; j < X->cols; j++)
      sm_set(*X_train, i, j, sm_get(X, i, j));
    for (size_t j = 0; j < Y->cols; j++)
      sm_set(*Y_train, i, j, sm_get(Y, i, j));
  }
  for (size_t i = 0; i < test_size; i++) {
    for (size_t j = 0; j < X->cols; j++)
      sm_set(*X_test, i, j, sm_get(X, train_size + i, j));
    for (size_t j = 0; j < Y->cols; j++)
      sm_set(*Y_test, i, j, sm_get(Y, train_size + i, j));
  }
}

static int progress_cb(const NmProgress *progress, void *user) {
  (void)user;
  if (progress->epoch % 20 == 0 || progress->epoch == progress->epochs)
    log_info("epoch %zu/%zu  loss=%.4f", progress->epoch, progress->epochs,
             progress->loss);
  return 0;
}

int main(void) {
  log_set_level(LOG_INFO);

  const char *data_file = "examples/moons/data/moons.csv";
  FloatMatrix *X_full = NULL;
  FloatMatrix *Y_full = NULL;
  size_t num_samples = 0;

  if (load_moons_dataset(data_file, &X_full, &Y_full, &num_samples) != 0) {
    log_error("Failed to load moons dataset");
    return EXIT_FAILURE;
  }
  log_info("Dataset loaded: %zu samples, 2 features, 2 classes", num_samples);

  normalize_features(X_full);
  log_info("Features normalized to [0, 1] range");

  FloatMatrix *X_train = NULL, *Y_train = NULL;
  FloatMatrix *X_test = NULL, *Y_test = NULL;
  split_dataset(X_full, Y_full, &X_train, &Y_train, &X_test, &Y_test);
  if (!X_train || !Y_train || !X_test || !Y_test) {
    log_error("Failed to split dataset");
    sm_destroy(X_full);
    sm_destroy(Y_full);
    return EXIT_FAILURE;
  }
  log_info("Train set: %zu samples, Test set: %zu samples", X_train->rows,
           X_test->rows);

  NmStatus s = NM_STATUS_OK;
  NmSpec *spec = NULL;
  NmNetwork *net = NULL;
  NmTensor y_train = tensor_view(Y_train);

  // MLP like the reference lab: 2 -> 16 -> 16 -> 2 (softmax)
  spec = nm_spec_new((NmShape){.ndim = 1, .dims = {2}});
  if (!spec) {
    log_error("Failed to create model spec: %s", nm_last_error());
    goto cleanup;
  }
  s = nm_spec_dense(spec, 16, NM_ACT_RELU);
  if (s == NM_STATUS_OK)
    s = nm_spec_dense(spec, 16, NM_ACT_RELU);
  if (s == NM_STATUS_OK)
    s = nm_spec_dense(spec, 2, NM_ACT_SOFTMAX);
  if (s != NM_STATUS_OK) {
    log_error("Failed to describe model: %s", nm_last_error());
    goto cleanup;
  }

  NmBuildOptions build = nm_build_options_default();
  build.seed = 42;
  net = nm_network_build(spec, &build);
  nm_spec_free(spec);
  spec = NULL;
  if (!net) {
    log_error("Failed to build model: %s", nm_last_error());
    goto cleanup;
  }

  NmFitOptions fit = nm_fit_options_default();
  fit.loss = NM_LOSS_CROSS_ENTROPY;
  fit.batch_size = 32;
  fit.learning_rate = 0.05f;
  fit.epochs = 500;
  fit.shuffle = true;

  log_info("Starting training: %zu epochs, batch_size=%zu, lr=%.4f",
           fit.epochs, fit.batch_size, fit.learning_rate);
  s = nm_network_fit(net, tensor_view(X_train), &y_train, &fit, progress_cb,
                     NULL);
  if (s != NM_STATUS_OK) {
    log_error("Training failed: %s", nm_last_error());
    goto cleanup;
  }

  NmMetrics train_metrics;
  s = nm_network_evaluate(net, tensor_view(X_train), tensor_view(Y_train),
                          NM_LOSS_CROSS_ENTROPY, &train_metrics);
  if (s != NM_STATUS_OK) {
    log_error("Training evaluation failed: %s", nm_last_error());
    goto cleanup;
  }
  log_info("Training Accuracy: %.2f%%", train_metrics.accuracy * 100.0f);

  NmMetrics test_metrics;
  s = nm_network_evaluate(net, tensor_view(X_test), tensor_view(Y_test),
                          NM_LOSS_CROSS_ENTROPY, &test_metrics);
  if (s != NM_STATUS_OK) {
    log_error("Test evaluation failed: %s", nm_last_error());
    goto cleanup;
  }

  NmTensor y_pred_test;
  s = nm_network_predict(net, tensor_view(X_test), &y_pred_test);
  if (s != NM_STATUS_OK) {
    log_error("Test prediction failed: %s", nm_last_error());
    goto cleanup;
  }

  log_info("Test Accuracy: %.2f%%", test_metrics.accuracy * 100.0f);
  log_info("Test Loss: %.4f", test_metrics.loss);

  // Print sample test predictions (first 10)
  log_info("Sample test predictions (first 10):");
  for (size_t i = 0; i < 10 && i < X_test->rows; i++) {
    float p0 = y_pred_test.data[i * 2];
    float p1 = y_pred_test.data[i * 2 + 1];
    int pred_class = p1 > p0 ? 1 : 0;
    int true_class = sm_get(Y_test, i, 1) > 0.5f ? 1 : 0;
    log_info("  Sample %zu: x=(%.3f, %.3f) -> Predicted: class %d (p=%.3f), "
             "True: class %d %s",
             i, sm_get(X_test, i, 0), sm_get(X_test, i, 1), pred_class,
             pred_class == 1 ? p1 : p0, true_class,
             pred_class == true_class ? "✓" : "✗");
  }
  nm_tensor_free(&y_pred_test);

cleanup:
  sm_destroy(X_full);
  sm_destroy(Y_full);
  sm_destroy(X_train);
  sm_destroy(Y_train);
  sm_destroy(X_test);
  sm_destroy(Y_test);
  nm_spec_free(spec);
  nm_network_free(net);

  return s == NM_STATUS_OK ? EXIT_SUCCESS : EXIT_FAILURE;
}
